=== IF shell pos = "v." / "v.t." / "v.i." (verb) ===
${verbBlocks || "(No verb-group or key-forms languages in target_languages)"}

=== IF shell pos = "adj." (adjective) ===
${adjBlocks || "(No adjective key-forms languages in target_languages)"}

